
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_14_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_14", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.171378352158702e+00, -5.072596419662124e+00, -4.933984130387522e+00, -4.741504255170937e+00, -4.478047835443198e+00, -4.124255122065531e+00, -3.659914320455647e+00, -3.063425030590131e+00, -2.308890276559875e+00, -1.439989852127386e+00, -7.882363714439974e-01, -5.983838491012978e-01, -6.348309410806802e-01, -5.478087870073453e-01, -3.590486235225250e-01, -1.762643191877587e-01, -7.010706386583046e-02, -2.252654399404666e-02, -4.812315583394840e-03, -5.410950161265856e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


